{"code": "export async function main(input: {}) {
  const { issues } = await sdk.sentry.listIssues({ project: "jobs" });
  const qualifying = issues
    .filter(i => i.project === "jobs" && i.status === "unresolved" && i.count >= 100)
    .sort((a, b) => a.shortId.localeCompare(b.shortId));

  const created = [];
  for (const i of qualifying) {
    const r = await sdk.linear.createIssue({
      title: `[Sentry] ${i.shortId}`,
      description: i.culprit,
    });
    created.push({ shortId: i.shortId, count: i.count, culprit: i.culprit, linear: r });
  }
  return { planned: qualifying.map(i => i.shortId), created };
}", "input": {}}

